d_hv:{t:"Ankündigung: Ablesung und Schornsteinfeger",lv:"B1",kind:"Schreiben der Hausverwaltung",from:"Hausverwaltung Neckar GmbH (Beispiel)",
 lines:["Hausverwaltung Neckar GmbH · An alle Mieter des Hauses Mönchhofstraße 12","Heidelberg, 04.01.2027","# Ablesung der Heizkostenverteiler und Wasserzähler · Termin des Schornsteinfegers","Sehr geehrte Mieterinnen und Mieter,","die jährliche Ablesung findet am **Dienstag, 19.01.2027, zwischen 8:00 und 12:00 Uhr** statt. Bitte sorgen Sie dafür, dass alle Heizkörper und Zähler frei zugänglich sind.","Sollten Sie zum genannten Termin verhindert sein, hinterlegen Sie bitte einen Schlüssel bei einem Nachbarn oder vereinbaren Sie **bis spätestens 15.01.2027** einen Ersatztermin unter Tel. 06221 000-0. Ein zweiter Ersatztermin ist kostenpflichtig.","Am selben Tag überprüft der bevollmächtigte Bezirksschornsteinfeger die Gasthermen. Diese Überprüfung ist gesetzlich vorgeschrieben; der Zutritt zur Wohnung ist zu gewähren.","Mit freundlichen Grüßen · i. A. Weber"],
 frist:["Dienstag, 19.01.2027, zwischen 8:00 und 12:00 Uhr","bis spätestens 15.01.2027"],
 gl:{Ablesung:"meter reading",Heizkostenverteiler:"heat-cost allocators (on the radiators)",Wasserzähler:"water meter",zugänglich:"accessible",verhindert:"unable to attend",hinterlegen:"to deposit, leave with someone",Ersatztermin:"alternative appointment",kostenpflichtig:"subject to a charge",bevollmächtigte:"authorised",vorgeschrieben:"prescribed, mandatory",Zutritt:"access",gewähren:"to grant"},
 q:[["Was passiert am 19. Januar?",["Die Zähler werden abgelesen, und der Schornsteinfeger kommt.","Die Heizung wird repariert.","Die Miete wird erhöht."],0],["Was kann man tun, wenn man an dem Tag arbeitet?",["einen Schlüssel beim Nachbarn lassen oder einen Ersatztermin vereinbaren","nichts, der Termin fällt dann aus","die Zähler selbst ablesen und nichts sagen"],0],["Darf man den Schornsteinfeger wegschicken?",["Nein, man muss ihn in die Wohnung lassen.","Ja, jederzeit.","Ja, wenn man keine Zeit hat."],0]],
 want:"Seien Sie am 19.01. vormittags zu Hause oder geben Sie einem Nachbarn den Schlüssel. Wenn das nicht geht: bis 15.01. anrufen und einen Ersatztermin vereinbaren.",wantEn:"Be at home on the morning of 19 January or leave a key with a neighbour; otherwise phone by 15 January for another appointment.",act:"termin",
 reply:{task:"Sie haben am 19.01. Frühdienst. Bitten Sie per E-Mail um einen Ersatztermin am Nachmittag oder am 20.01.",model:"Sehr geehrter Herr Weber, am 19.01.2027 bin ich leider verhindert, da ich Frühdienst habe. Ich bitte um einen Ersatztermin am Nachmittag oder am 20.01.",need:["verhindert|nicht zu hause|nicht da|frühdienst","ersatztermin|anderen termin|neuen termin"]}},
d_nk:{t:"Nebenkostenabrechnung 2026",lv:"B2",kind:"Abrechnung",from:"Hausverwaltung Neckar GmbH (Beispiel)",
 lines:["Hausverwaltung Neckar GmbH · Heidelberg, 12.05.2027","# Betriebskostenabrechnung für den Zeitraum 01.01.2026 – 31.12.2026","Wohnung 3. OG links · Wohnfläche 62,00 m² von 496,00 m² · Nutzungszeitraum laut Abrechnung: 12 Monate","Heizung und Warmwasser (nach Verbrauch) :: 1.104,00 €","Wasser / Abwasser :: 388,00 €","Müllabfuhr :: 212,00 €","Hausreinigung, Hausmeister :: 436,00 €","Grundsteuer :: 268,00 €","Gebäudeversicherung :: 174,00 €","Reparatur Dach (anteilig) :: 370,00 €","Summe der Kosten :: 2.952,00 €","abzüglich Ihrer Vorauszahlungen (12 × 220,00 €) :: − 2.640,00 €","**Nachzahlung** :: **312,00 €**","Bitte überweisen Sie den Betrag **bis zum 15.06.2027**. Ihre monatliche Vorauszahlung erhöht sich ab 01.07.2027 auf 246,00 €.","Einwendungen gegen diese Abrechnung sind innerhalb von zwölf Monaten nach Zugang mitzuteilen. Die Belege können nach Terminvereinbarung eingesehen werden."],
 frist:["bis zum 15.06.2027","innerhalb von zwölf Monaten"],
 gl:{Betriebskostenabrechnung:"service-charge statement",Zeitraum:"period",Wohnfläche:"floor area",Verbrauch:"consumption",Grundsteuer:"property tax",anteilig:"proportionate share",abzüglich:"less, minus",Vorauszahlungen:"advance payments",Nachzahlung:"back-payment",Einwendungen:"objections",Zugang:"receipt (of a letter)",Belege:"receipts, vouchers"},
 q:[["Wie viel soll Herr Ismail nachzahlen?",["312,00 €","2.952,00 €","246,00 €"],0],["Welcher Fehler steckt in der Abrechnung? Er ist erst im Dezember 2026 eingezogen.",["Es wurden zwölf Monate berechnet statt einem.","Die Wohnfläche ist zu klein angegeben.","Die Müllabfuhr fehlt."],0],["Welche Position darf der Vermieter nicht umlegen?",["Reparatur Dach","Grundsteuer","Müllabfuhr"],0],["Wie lange hat er Zeit für Einwände?",["zwölf Monate nach Zugang","bis zum 15.06.2027","einen Monat"],0]],
 want:"Die Hausverwaltung will 312 Euro bis zum 15.06.2027 und ab Juli eine höhere Vorauszahlung. Prüfen Sie zuerst: Zeitraum, Fläche, Positionen. Hier stimmen zwei Dinge nicht – also nicht einfach zahlen, sondern schriftlich Einwände erheben.",wantEn:"They want 312 euros by 15 June and a higher advance from July. Check period, area and items first: two things are wrong here, so object in writing rather than simply pay.",act:"widerspruch",
 reply:{task:"Erheben Sie schriftlich Einwände: (1) Einzug erst am 28.11.2026, (2) Dachreparatur nicht umlagefähig. Bitten Sie um eine korrigierte Abrechnung.",model:"Sehr geehrter Herr Weber, gegen die Betriebskostenabrechnung 2026 erhebe ich Einwände. Ich bin erst am 28.11.2026 eingezogen, abgerechnet wurden jedoch zwölf Monate. Außerdem sind Reparaturen nicht umlagefähig. Ich bitte um eine korrigierte Abrechnung.",need:["einwände|einwendungen|widerspreche|einspruch","eingezogen","reparatur","korrigierte"]}},
